import path from"node:path";import fs from"node:fs";import knexFactory from"knex";import{getGlobalVariables}from"./action/setup-global-variables.js";import{isPro}from"./common/other-tools.js";function resolveDbPath(){return getGlobalVariables("sqliteDbPath")||path.join(process.cwd(),"data",isPro()?"pro":"dev","dumogu.db")}const dbPath=resolveDbPath();fs.mkdirSync(path.dirname(dbPath),{recursive:!0});export const db=knexFactory({client:"better-sqlite3",connection:{filename:dbPath},useNullAsDefault:!0});export async function bootstrap(){await db.schema.hasTable("user")||await db.schema.createTable("user",t=>{t.string("id").primary(),t.bigInteger("initDate").notNullable().defaultTo(0),t.bigInteger("updateDate").notNullable().defaultTo(0),t.string("name").notNullable().defaultTo(""),t.string("nickname").notNullable().defaultTo(""),t.string("templatePassword").notNullable().defaultTo(""),t.integer("saltRounds").notNullable().defaultTo(7),t.string("password").notNullable().defaultTo(""),t.integer("signSaltRounds").notNullable().defaultTo(7),t.string("signPassword").notNullable().defaultTo(""),t.string("synopsis").notNullable().defaultTo(""),t.string("avatar").notNullable().defaultTo(""),t.string("favicon").notNullable().defaultTo(""),t.text("about").notNullable().defaultTo(""),t.string("giscusDataRepo").notNullable().defaultTo(""),t.string("giscusDataRepoId").notNullable().defaultTo(""),t.string("giscusDataCategory").notNullable().defaultTo(""),t.string("giscusDataCategoryId").notNullable().defaultTo(""),t.string("siteCountScript").notNullable().defaultTo("")}),await db.schema.hasTable("token")||await db.schema.createTable("token",t=>{t.string("id").primary(),t.bigInteger("initDate").notNullable().defaultTo(0),t.bigInteger("updateDate").notNullable().defaultTo(0),t.string("userId").notNullable().defaultTo(""),t.string("token").notNullable().defaultTo("")}),await db.schema.hasTable("friendly_link")||await db.schema.createTable("friendly_link",t=>{t.string("id").primary(),t.string("name").notNullable().defaultTo(""),t.string("content").notNullable().defaultTo(""),t.string("link").notNullable().defaultTo(""),t.string("icon").notNullable().defaultTo(""),t.boolean("hidden").notNullable().defaultTo(!1),t.bigInteger("initDate").notNullable().defaultTo(0),t.bigInteger("updateDate").notNullable().defaultTo(0)})}